from pathlib import Path
from lesson_authoring import entry as E
N=[['拉丁 nōn → 古法语／盎格鲁法语 non- → 英语 non-','不、没有；否定后面的性质']]
CH=[['拉丁 nōn“不是” + calēre“热”相关的法语支线','热的意象 → 关心、在意'],['古法语 non- + chaloir → nonchaloir／nonchalant','不关切 → 不慌不忙、漫不经心']]
def H(w,meaning):return N+[['英语 non- + '+w,meaning]]
W=[
E('nonexistent','英 /ˌnɒnɪɡˈzɪstənt/；美 /ˌnɑːnɪɡˈzɪstənt/','不存在的；几乎没有的','找不到那个东西，不是它太少被忽略，而是根本没有。','non-“不” + existent“存在的”；existent 接拉丁 exsistere“出现、存在”。',H('existent → nonexistent','存在的 → 不存在的'),'a nonexistent address 是不存在的地址；customer service was nonexistent 常是夸张说服务几乎等于没有。它否定的是存在，不等于说东西有缺点。','a nonexistent problem；virtually nonexistent；almost nonexistent。','invisible 是存在但看不见；nonexistent 是不存在。不能把这两个“看不到”混成一回事。',('The email was sent to a nonexistent address.','邮件被发到了一个不存在的地址。'),('Public transport is almost nonexistent in the village.','村里几乎没有公共交通。'),sources=['https://www.merriam-webster.com/dictionary/nonexistent','https://www.etymonline.com/word/existent']),
E('noninvasive','英 /ˌnɒnɪnˈveɪsɪv/；美 /ˌnɑːnɪnˈveɪsɪv/','非侵入性的；非侵袭性的','要了解里面的情况，但不把器械穿过身体表面或伸进身体开口。','non-“不” + invasive“侵入的”；invasive 接 invade 所属的拉丁 invadere 词族。',H('invasive → noninvasive','侵入的 → 不侵入的'),'noninvasive test 常指不把器械侵入身体的检查，例如体表超声。说肿瘤 noninvasive 时，重点则是尚未侵入起源组织之外；同一形容词随对象改变具体意思。','a noninvasive test；noninvasive monitoring；a noninvasive procedure。','minimally invasive 是侵入程度较小；noninvasive 是非侵入。两者谈的是检查或治疗怎样接触身体。',('The team developed a noninvasive method for monitoring the signal.','团队开发了一种无需侵入身体即可监测该信号的方法。'),('The doctor explained that this was a noninvasive test.','医生解释说，这是一项无创检查。'),sources=['https://www.cancer.gov/publications/dictionaries/cancer-terms/def/noninvasive']),
E('nonfiction','英 /ˌnɒnˈfɪkʃən/；美 /ˌnɑːnˈfɪkʃən/','非虚构作品；纪实类写作','作品以真实人物、事件或知识为对象，写作承诺是讲事实。','non-“非” + fiction“虚构作品”。',H('fiction → nonfiction','虚构 → 以事实为对象的作品类别'),'传记、历史、科学普及等都可以是 nonfiction。这个分类说明作品的写作目标，不保证其中每个判断都没有错误；非虚构也完全可以有生动的故事和场景。','read nonfiction；a nonfiction book；narrative nonfiction。','fiction 可以借真实背景编故事；nonfiction 以事实为主要依据，不等于“没有故事性”。',('She reads more nonfiction than novels.','她读的非虚构作品比小说多。'),('The library has a separate shelf for children’s nonfiction.','图书馆设有专门摆放儿童非虚构读物的书架。')),
E('nonverbal','英 /ˌnɒnˈvɜːbəl/；美 /ˌnɑːnˈvɜːrbəl/','非言语的；不通过说话表达的','不靠说出一句话，也能把意思传出去：一个眼神、手势或停顿就够了。','non-“非” + verbal“言语的”。',H('verbal → nonverbal','言语的 → 通过言语以外方式表达的'),'nonverbal communication 包括面部表情、手势等。描述某人 nonverbal 时，通常关注其不使用或很少使用口语表达，不代表他没有想法、不能理解或不能用其他方式交流。','nonverbal communication；nonverbal cues；nonverbal expression。','silent 只说没有声音；nonverbal 关注表达方式，拍手、动作等也可以传达信息。',('Her smile was a clear nonverbal sign of approval.','她的微笑是一个明确的非言语赞许信号。'),('The course teaches students to recognise nonverbal cues.','这门课教学生识别非言语线索。'),sources=['https://www.merriam-webster.com/dictionary/nonverbal']),
E('nonessential','英 /ˌnɒnɪˈsenʃəl/；美 /ˌnɑːnɪˈsenʃəl/','非必需的；可省去的','有它可能更方便，但当前这件事没有它也能完成。','non-“非” + essential“必不可少的”。',H('essential → nonessential','必需的 → 并非必需的'),'nonessential spending 是可减少的非必要开支；nonessential details 是不影响核心信息的细节。它说的是当前目的下是否必需，不自动等于没价值。','nonessential spending；nonessential details；nonessential equipment。','unnecessary 更容易表示根本没必要；nonessential 常用于区分必需与可选，语气比较分类化。',('We cut nonessential spending for three months.','我们连续三个月削减了非必要开支。'),('Remove the nonessential details from the summary.','把摘要中非必要的细节删掉。')),
E('nonviolent','英 /ˌnɒnˈvaɪələnt/；美 /ˌnɑːnˈvaɪələnt/','非暴力的；不使用暴力的','可以坚持反对、积极争取，但不通过伤害或暴力来做。','non-“不、非” + violent“暴力的”。',H('violent → nonviolent','暴力的 → 不使用暴力的'),'a nonviolent protest 可以很坚定、很有组织。这个词否定暴力方式，没有否定行动本身，也不等于所有人意见一致或场面毫无紧张。','nonviolent protest；nonviolent resistance；a nonviolent approach。','passive 是被动的；nonviolent 是不用暴力的，积极行动也可以 nonviolent。',('The organisers called for a nonviolent protest.','组织者呼吁进行非暴力抗议。'),('They sought a nonviolent way to resolve the dispute.','他们寻求用非暴力方式解决争端。'),sources=['https://www.merriam-webster.com/dictionary/nonviolent']),
E('nonviolence','英 /ˌnɒnˈvaɪələns/；美 /ˌnɑːnˈvaɪələns/','非暴力；不使用暴力的原则或实践','把不用暴力当作一种做事原则，而不只描述某一次场面很安静。','non-“非” + violence“暴力”。',H('violence → nonviolence','暴力 → 不使用暴力的立场、做法'),'commitment to nonviolence 是坚持非暴力原则。它可以包含抗议、谈判、抵制等积极行动；有没有效果是另一个问题，不能从词本身就推出。','a commitment to nonviolence；the principle of nonviolence。','nonviolent 是形容词，描述行动或人；nonviolence 是名词，谈原则、方法或状态。',('The movement made a public commitment to nonviolence.','这场运动公开承诺坚持非暴力。'),('The lesson explored the difference between nonviolence and inaction.','这堂课探讨了非暴力与不采取行动的区别。')),
E('nonstop','英 /ˌnɒnˈstɒp/；美 /ˌnɑːnˈstɑːp/','不停的；中途不停站的；连续不断地','从开始到结束，中间不按暂停键。','non-“不” + stop“停止”。',H('stop → nonstop','停止 → 不停、不中断'),'a nonstop flight 中途不停落；work nonstop 是连续工作。说话中的 nonstop questions 常带夸张，表示问题接连不断，不要求真的每一秒都有声音。','a nonstop flight；nonstop service；talk nonstop。','direct flight 强调直达航班安排，可能中停；nonstop 明确突出中途不停站。',('We booked a nonstop flight to Singapore.','我们订了直飞新加坡、中途不停站的航班。'),('The children talked nonstop on the way home.','孩子们在回家的路上说个不停。')),
E('nonconformity','英 /ˌnɒnkənˈfɔːmɪti/；美 /ˌnɑːnkənˈfɔːrmɪti/','不遵从；不合惯例；不符合要求','大家沿着同一个模子做，你没有照那个模子来。','non-“不” + conformity“遵从、符合”；早期英语与不遵从国教规范的宗教语境密切相关。',H('conformity → nonconformity','遵从既定规范 → 不遵从、不一致'),'在生活风格里 nonconformity 可以是不随大流；在质量检查里则可能是不符合某项要求。词本身没有固定的赞美或批评，所处场景决定语气。','social nonconformity；nonconformity with requirements；religious nonconformity。','individuality 是个人特点，不一定违反规则；nonconformity 明确与某种惯例、规范或要求不一致。',('The school encouraged creativity and tolerated some nonconformity.','学校鼓励创造力，也容许一定程度的不循常规。'),('The inspection identified nonconformity with the specified requirements.','检查发现了不符合规定要求的情况。'),sources=['https://www.etymonline.com/word/nonconformity']),
E('nonchalant','英 /ˈnɒnʃələnt/；美 /ˌnɑːnʃəˈlɑːnt/','若无其事的；漫不经心的；从容随意的','别人可能紧张，你却轻轻耸一下肩，像没什么大不了。','整体借自法语 nonchalant；non-“不” + chaloir“关心、在意”，后者远接拉丁 calēre“热”。',CH+[['法语 nonchalant → 英语 nonchalant','不关切的 → 从容随意、显得不在意的']],'a nonchalant shrug 是若无其事地耸肩。它可以欣赏一个人的从容，也可以批评他对重要事情太不上心；还可能只是装出来的轻松。','a nonchalant smile；a nonchalant shrug；try to look nonchalant。','calm 主要说平静；nonchalant 常多一层“显得这事不值得太在意”。不要把它当成 nonplussed“困惑”的常规同义词。',('He gave a nonchalant shrug and changed the subject.','他若无其事地耸耸肩，换了话题。'),('She tried to sound nonchalant, but her hands were shaking.','她努力让声音显得轻松，双手却在发抖。'),sources=['https://www.etymonline.com/word/nonchalant','https://en.wiktionary.org/wiki/nonchalant']),
E('nonchalance','英 /ˈnɒnʃələns/；美 /ˌnɑːnʃəˈlɑːns/','若无其事；漫不经心；从容随意的态度','把那种“这有什么”的神态和态度，作为一个特点说出来。','整体借自法语 nonchalance；与法语 nonchalant 同族，不能把英语先后顺序简单写成先形容词再造名词。',CH+[['法语 nonchalance → 英语 nonchalance','不关切的态度 → 随意、从容或漫不经心']],'with apparent nonchalance 是表面上若无其事；an air of nonchalance 是一种满不在乎的样子。它强调表现出来的态度，未必反映内心是否紧张。','with nonchalance；an air of nonchalance；apparent nonchalance。','nonchalant 修饰人、神态或动作；nonchalance 直接把这种态度当作名词来谈。',('She accepted the news with surprising nonchalance.','她出人意料地平静随意地接受了这个消息。'),('His apparent nonchalance hid a great deal of anxiety.','他表面上的若无其事掩盖了内心的强烈焦虑。'),sources=['https://www.etymonline.com/word/nonchalance','https://en.wiktionary.org/wiki/nonchalance']),
]
ROOT=dict(id='C0822',meaning='不、没有；非某类',core='NON = NOT / WITHOUT',image='给一个分类框画一条边界：在“必需”之外是 nonessential，在“虚构作品”之外是 nonfiction。它常只是说“不属于这一类”，不自动给事物贴上好坏标签。',intro='non- 严格说是前缀，主要经法语进入英语，来自拉丁 nōn“不”。英语大量用它与已有词组合；另一些词如 nonchalant 则是把法语整词借进来，不能当作英语现拼。',forms='non- 通常不改变后面的词形。nonfiction、nonstop 等已有合写形式，本页按要求不列带连字符的词头。none“一个也没有”来自古英语 nān，虽与拉丁 nōn 有可比较的否定构造，也不能写成从拉丁 non- 直接演变。',branches=[['不存在或不具某性质','nonexistent, nonessential, nonlinear, noninvasive'],['不用某种表达、行动方式','nonverbal, nonviolent, nonviolence'],['作品、组织和连续性分类','nonfiction, nonprofit, nonstop'],['不合规范或常理','nonconformist, nonconformity, nonsense'],['需要记住整条历史的旧词','nonchalant, nonchalance, nonplus, nonplussed']],contrasts='non- 常用于分类式否定，un- 常形成另一个相对性质，但不能机械互换。nonchalant 常是若无其事；nonplussed 的传统核心义是困惑、不知如何回应。none 的古英语路线与本页的法语、拉丁借入路线分开。',practice='The nonfiction section was almost empty. A nonchalant assistant pointed to a note explaining that the books had been moved upstairs.\n\n非虚构读物区几乎空了。一位神态随意的店员指了指通知，上面说书已经搬到楼上。',words=[w['word'] for w in W]+['nonprofit','nonsense','nonlinear','nonconformist','nonplus','nonplussed'],exclude={'none':'代词 none 来自古英语 nān，不是拉丁否定前缀 non- 的借入后代；同形古旧时刻义则来自拉丁 nona“第九”，另属九的词族。'})
if __name__=='__main__':
 for name,v in [('roots_non',[ROOT]),('words_non',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(v,ensure_ascii=False,indent=2))
 print(len(W),'individually authored words')
